    Bug 1893146 - Try to fix intermittent comm/mail/base/test/widgets/browser_treeView.js | Uncaught exception in test bound testKeyboardAndMouse - 'select' event should get fired - timed out after 50 tries. r=tobyp

    Obviously not the ideal fix. It does seem the row is there, but clicking on in with --headless does not work for some reason. It doesn't appear to be a timing issue either.
    The normal way works in general - for me at least the failing case is index 12 - https://searchfox.org/comm-central/rev/cb79cdf1d4fccd774ca03a05539640eba9bb6f24/mail/base/test/widgets/browser_treeView.js#670
    I don't know if it's a code issue or some oddness in headless mode. Nevertheless, it makes finding issues with (--headless --verify) impossible.

    Differential Revision: https://phabricator.services.mozilla.com/D226610

diff --git a/mail/base/test/widgets/browser_treeView.js b/mail/base/test/widgets/browser_treeView.js
index 0b6e9ddd418..027f7a4f7ff 100644
--- a/mail/base/test/widgets/browser_treeView.js
+++ b/mail/base/test/widgets/browser_treeView.js
@@ -263,7 +263,17 @@ async function subtestKeyboardAndMouse(variant) {

     selectHandler.reset();
     list.addEventListener("select", selectHandler, { once: true });
-    EventUtils.synthesizeMouse(list, x, y, modifiers, content);
+
+    let row = list.ownerDocument.elementFromPoint(x, y);
+    if (!row) {
+      // Happens for some cases with --headless at least.
+      info(`Found no row ${index} at ${x},${y}`);
+      row = list.querySelectorAll(`tr[is="test-row"]`)[index];
+      row.click();
+    } else {
+      EventUtils.synthesizeMouse(list, x, y, modifiers, content);
+    }
+
     await TestUtils.waitForCondition(
       () => !!selectHandler.seenEvent == expectEvent,
       `'select' event should ${expectEvent ? "" : "not "}get fired`
